.wf-inv {
    --inv-surface: var(--main-background1, var(--wf-color-surface, light-dark(#fff, #101a2b)));
    --inv-raised: var(--main-background2, var(--wf-color-background, light-dark(#f3f6fa, #162235)));
    --inv-text: var(--main-font-color, var(--wf-color-text, light-dark(#15253a, #e5edf8)));
    --inv-muted: var(--main-font-color-light, var(--wf-color-muted, light-dark(#4e6075, #b3c3d7)));
    --inv-line: var(--main-boder-color, var(--wf-color-border, light-dark(#d6dde6, #40516a)));
    --inv-accent: var(--main-button-background, var(--wf-color-primary, light-dark(#167261, #25d9c5)));
    --inv-accent-text: var(--main-button-font-color, var(--wf-color-on-primary, light-dark(#fff, #101a2b)));
    box-sizing: border-box;
    display: grid;
    grid-template-columns: 228px minmax(0, 1fr);
    gap: 24px;
    width: min(100%, 1216px);
    margin-inline: auto;
    padding: 32px clamp(16px, 3vw, 32px) 48px;
    color: var(--inv-text);
    font-size: 14px;
}
.wf-inv *, .wf-inv *::before, .wf-inv *::after { box-sizing: border-box; }
.wf-inv [hidden] { display: none !important; }
.wf-inv-filters, .wf-inv-card, .wf-inv-empty {
    background: var(--inv-surface);
    border: 1px solid var(--inv-line);
    border-radius: 8px;
}
.wf-inv-filters { padding: 16px; }
.wf-inv-filters h2, .wf-inv h1 { margin: 0; font-weight: 700; }
.wf-inv-filters h2 { color: var(--inv-muted); font-size: 12px; }
.wf-inv h1 { font-size: 24px; line-height: 1.25; }
.wf-inv-option {
    display: grid;
    grid-template-columns: auto minmax(0, 1fr) auto;
    align-items: center;
    gap: 8px;
    min-height: 36px;
    margin-top: 4px;
    font-size: 13px;
    cursor: pointer;
}
.wf-inv-option input { accent-color: var(--inv-accent); }
.wf-inv-count { color: var(--inv-muted); font-variant-numeric: tabular-nums; font-size: 12px; }
.wf-inv-feedback, .wf-inv-meta, .wf-inv-date { color: var(--inv-muted); font-size: 12px; }
.wf-inv-list { display: grid; gap: 10px; margin: 16px 0 0; padding: 0; list-style: none; }
.wf-inv-card { display: grid; gap: 6px; padding: 14px 16px; }
.wf-inv-row { display: flex; flex-wrap: wrap; align-items: center; gap: 8px; }
.wf-inv-card strong { font-size: 17px; }
.wf-inv-amount { margin-inline-start: auto; font-variant-numeric: tabular-nums; font-weight: 650; }
.wf-inv-badge {
    display: inline-block;
    padding: 1px 8px;
    border: 1px solid color-mix(in srgb, var(--inv-status, var(--inv-text)) 36%, var(--inv-line));
    border-radius: 999px;
    color: color-mix(in srgb, var(--inv-status, var(--inv-text)) 36%, var(--inv-text));
    background: color-mix(in srgb, var(--inv-status, var(--inv-surface)) 13%, var(--inv-surface));
    font-size: 12px;
    font-weight: 600;
}
.wf-inv-badge[data-status="paid"] { --inv-status: #167261; }
.wf-inv-badge[data-status="partial"] { --inv-status: #9a6700; }
.wf-inv-badge[data-status="unpaid"] { --inv-status: #8d3b3b; }
.wf-inv-empty { margin: 16px 0 0; padding: 24px 12px; text-align: center; color: var(--inv-muted); }
.wf-inv [data-inv-retry] {
    min-height: 36px;
    margin-top: 12px;
    padding: 6px 10px;
    border: 1px solid var(--inv-line);
    border-radius: 4px;
    background: var(--inv-surface);
    color: var(--inv-text);
    font: inherit;
}
@media (max-width: 720px) {
    .wf-inv { grid-template-columns: minmax(0, 1fr); padding-block: 20px 32px; }
    .wf-inv h1 { font-size: 20px; }
    .wf-inv-option { min-height: 44px; }
}

scripts.content:
(function () {
    'use strict';

    function decode(binding) {
        const bytes = Uint8Array.from(atob(binding.replace(/-/g, '+').replace(/_/g, '/')), value => value.charCodeAt(0));
        return JSON.parse(new TextDecoder().decode(bytes));
    }

    function encode(input) {
        const bytes = new TextEncoder().encode(JSON.stringify(input));
        let text = '';
        bytes.forEach(value => { text += String.fromCharCode(value); });
        return btoa(text).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
    }

    function node(tag, value, className) {
        const element = document.createElement(tag);
        element.textContent = value;
        if (className) element.className = className;
        return element;
    }

    function money(amount, currency) {
        const number = Number(amount);
        const shown = Number.isFinite(number) ? number.toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 }) : amount;
        return shown + (currency ? ' ' + currency : '');
    }

    function init(host) {
        const section = host.querySelector('.wf-inv');
        if (!section || section.dataset.invReady) return;
        section.dataset.invReady = 'true';
        const english = document.documentElement.lang.toLowerCase().split('-')[0] === 'en';
        const t = (sr, en) => english ? en : sr;
        const labels = { paid: t('Plaćeno', 'Paid'), partial: t('Delimično', 'Partial'), unpaid: t('Nije plaćeno', 'Unpaid') };
        const feedback = section.querySelector('[data-inv-feedback]');
        const list = section.querySelector('[data-inv-list]');
        const empty = section.querySelector('[data-inv-empty]');
        const retry = section.querySelector('[data-inv-retry]');
        const types = section.querySelector('[data-inv-types]');
        const selected = new Set();
        const preview = host.dataset.wfProviderPreview ? decode(host.dataset.wfProviderPreview) : null;
        let request;

        function paint(data) {
            types.replaceChildren(...data.types.map(entry => {
                const option = node('label', '', 'wf-inv-option');
                const input = document.createElement('input');
                input.type = 'checkbox';
                input.value = entry.label;
                input.checked = selected.has(entry.label);
                option.append(input, node('span', entry.label), node('span', String(entry.count), 'wf-inv-count'));
                return option;
            }));
            empty.hidden = data.items.length !== 0;
            empty.textContent = t('Nema faktura za prikaz.', 'No invoices to show.');
            feedback.textContent = data.types.reduce((sum, entry) => sum + entry.count, 0) + t(' dokumenata', ' documents');
            list.replaceChildren(...data.items.map(item => {
                const row = document.createElement('li');
                const card = node('article', '', 'wf-inv-card');
                const meta = node('div', '', 'wf-inv-row');
                const badge = node('span', labels[item.status] || item.status, 'wf-inv-badge');
                badge.dataset.status = item.status;
                const date = item.date ? item.date.slice(0, 10).split('-').reverse().join('.') + '.' : '';
                meta.append(badge, node('span', item.number, 'wf-inv-meta'), node('time', date, 'wf-inv-date'));
                const amount = node('div', '', 'wf-inv-row');
                amount.append(node('strong', item.type || t('Faktura', 'Invoice')), node('span', money(item.amount, item.currency), 'wf-inv-amount'));
                card.append(meta, amount);
                if (item.status === 'partial') {
                    card.append(node('span', t('Preostalo ', 'Remaining ') + money(item.remaining, item.currency), 'wf-inv-meta'));
                }
                row.append(card);
                return row;
            }));
        }

        async function load() {
            request?.abort();
            request = new AbortController();
            const current = request;
            list.setAttribute('aria-busy', 'true');
            retry.hidden = true;
            feedback.textContent = t('Učitavanje faktura…', 'Loading invoices…');
            try {
                const input = {};
                if (selected.size) input.types = [...selected];
                let data = preview;
                if (!preview) {
                    const url = new URL(host.dataset.wfProviderUrl, window.location.href);
                    url.searchParams.set('wf_input', encode(input));
                    const response = await fetch(url, { credentials: 'same-origin', cache: 'no-store', signal: current.signal });
                    if (!response.ok) throw new Error(String(response.status));
                    const result = await response.json();
                    if (!result.ok) throw new Error('Provider response');
                    data = result.data;
                } else if (selected.size) {
                    data = { ...preview, items: preview.items.filter(item => selected.has(item.type)) };
                }
                if (request === current) paint(data);
            } catch (error) {
                if (request !== current) return;
                list.replaceChildren();
                empty.hidden = true;
                feedback.textContent = t('Fakture trenutno nisu dostupne.', 'Invoices are currently unavailable.');
                retry.hidden = false;
            } finally {
                if (request === current) list.removeAttribute('aria-busy');
            }
        }

        types.addEventListener('change', event => {
            const input = event.target;
            if (input.type !== 'checkbox') return;
            if (input.checked) {
                if (selected.size >= 4) { input.checked = false; return; }
                selected.add(input.value);
            } else {
                selected.delete(input.value);
            }
            load();
        });
        retry.addEventListener('click', load);
        load();
    }

    document.querySelectorAll('[data-wf-component="invoice-overview"]').forEach(init);
}());
